1	package netdiag
2	
3	import (
4		"strings"
5	
6		"charm.land/lipgloss/v2"
7	
8		"github.com/anthnel/devdesk/internal/netcheck"
9		"github.com/anthnel/devdesk/internal/ui/components"
10		"github.com/anthnel/devdesk/internal/ui/help"
11		"github.com/anthnel/devdesk/internal/ui/indicator"
12		"github.com/anthnel/devdesk/internal/ui/keymap"
13		"github.com/anthnel/devdesk/internal/ui/shortcut"
14		"github.com/anthnel/devdesk/internal/ui/theme"
15	)
16	
17	// GetTitle implements HeaderView
18	func (m *Model) GetTitle() string {
19		base := theme.IconNetwork + " Network"
20		if m.activeTab == tabDiagnostics && m.state == StateTrace {
21			return m.traceTitle(base)
22		}
23		if m.state == StateDetails {
24			if label := m.selected.Title; label != "" {
25				return base + titleTrailStyle().Render(" "+theme.IconChevronRight+" "+label)
26			}
27		}
28		return base
29	}
30	
31	// GetIcon implements HeaderView
32	func (m *Model) GetIcon() string {
33		return theme.IconNetwork
34	}
35	
36	// GetShortcuts implements HeaderView
37	func (m *Model) GetShortcuts() shortcut.Shortcuts {
38		tabShortcuts := shortcut.Shortcuts{
39			{Key: "tab", Description: "Switch tab"},
40		}
41	
42		if m.activeTab == tabInterfaces {
43			// A read in flight greys the table's keys rather than removing them:
44			// the tab is the same screen either side of a refresh, and a column
45			// that empties and refills on every ctrl+r is the flicker Rule 130 is
46			// about. ctrl+r stays lit — asking again is exactly what still applies.
47			loading := m.interfacesModel.loading
48			return append(tabShortcuts, shortcut.Shortcuts{
49				{Key: "ctrl+r", Description: "Refresh"},
50				{Key: "/", Description: "Filter", Disabled: loading},
51				{Key: ".", Description: "Sort", Disabled: loading},
52				{Key: "?", Description: "Help"},
53			}...)
54		}
55	
56		if m.activeTab == tabForward {
57			if m.forwardModel.form != nil {
58				// A form is a mode, so the whole list is replaced rather than
59				// greyed (Rule 130): greying N and K here would show the union of
60				// two vocabularies.
61				return shortcut.Shortcuts{
62					// ←→ only cycles the type, so it greys elsewhere (Rule 130).
63					{Key: "←→", Description: "Change type", Disabled: !m.forwardModel.form.TypeFocused()},
64					{Key: "enter", Description: "Open the forward"},
65					{Key: "esc", Description: "Cancel"},
66				}
67			}
68			if m.forwardModel.table.FilterBar().InEditMode() {
69				return shortcut.Shortcuts{
70					{Key: "enter/esc", Description: "Confirm / Cancel search"},
71				}
72			}
73			return append(tabShortcuts, shortcut.Shortcuts{
74				{Key: keymap.New, Description: "New forward"},
75				// Nothing to pause, resume or delete on an empty table (Rule 130).
76				{Key: "space", Description: m.forwardModel.toggleLabel(), Disabled: !m.forwardModel.switchable().Enabled()},
77				{Key: keymap.Kill, Description: "Delete forward", Disabled: !m.forwardModel.closable().Enabled()},
78				{Key: "/", Description: "Search"},
79				{Key: ".", Description: "Sort"},
80				{Key: "?", Description: "Help"},
81			}...)
82		}
83	
84		if m.activeTab == tabPorts {
85			if m.portsModel.table.FilterBar().InEditMode() {
86				return shortcut.Shortcuts{
87					{Key: "enter/esc", Description: "Confirm / Cancel search"},
88				}
89			}
90			sc := shortcut.Shortcuts{
91				{Key: "t", Description: "Toggle TCP"},
92				{Key: "u", Description: "Toggle UDP"},
93				{Key: "l", Description: "Toggle LISTEN"},
94				{Key: "e", Description: "Toggle ESTAB"},
95				{Key: "n", Description: "Toggle numeric"},
96				{Key: "z", Description: "Reset filters"},
97				{Key: "/", Description: "Search"},
98				{Key: "space", Description: "Pause/Resume"},
99				// A socket the system declines to attribute carries no PID, so
100				// there is nothing to signal (Rule 130).
101				{Key: keymap.Kill, Description: "Kill process", Disabled: !m.portsModel.killable().Enabled()},
102				{Key: "?", Description: "Help"},
103			}
104			return append(tabShortcuts, sc...)
105		}
106	
107		switch m.state {
108		case StateTrace:
109			return m.traceShortcuts()
110		case StateInput:
111			enter := shortcut.Shortcut{Key: "enter", Description: "Run the checks"}
112			if m.focusedField == fieldTraceButton {
113				enter = shortcut.Shortcut{Key: "enter", Description: "Trace the path", Disabled: !m.traceable().Enabled()}
114			}
115			return append(tabShortcuts, shortcut.Shortcuts{
116				enter,
117				{Key: "?", Description: "Help"},
118			}...)
119		case StateRunning:
120			return shortcut.Shortcuts{
121				{Key: "esc", Description: "Cancel and keep what completed"},
122			}
123		case StateResults:
124			if m.filterBar.InEditMode() {
125				return shortcut.Shortcuts{
126					{Key: "enter/esc", Description: "Confirm / Cancel search"},
127				}
128			}
129			sc := shortcut.Shortcuts{
130				{Key: "enter", Description: "Explain the check"},
131			}
132			label := "Show problems only"
133			if m.filterBar.IsTokenActive(problemsToken) {
134				label = "Show every check"
135			}
136			escLabel := "New diagnostic"
137			if m.OriginView != "" {
138				escLabel = "Go back"
139			}
140			sc = append(sc,
141				shortcut.Shortcut{Key: "p", Description: label},
142				shortcut.Shortcut{Key: "/", Description: "Search"},
143				shortcut.Shortcut{Key: keymap.Diagnose, Description: "Trace the path", Disabled: !m.pathFromRoute().Enabled()},
144				shortcut.Shortcut{Key: "ctrl+r", Description: "Run again"},
145				shortcut.Shortcut{Key: "esc", Description: escLabel},
146			)
147			if m.OriginView != "" {
148				// Otherwise esc already reads "New diagnostic" and does exactly
149				// this — advertising both here would just say the same thing
150				// twice (Rule 138). With an origin, esc means "go back" instead,
151				// so this is the only key left that starts a fresh target.
152				sc = append(sc, shortcut.Shortcut{Key: keymap.New, Description: "New diagnostic"})
153			}
154			sc = append(sc, shortcut.Shortcut{Key: "?", Description: "Help"})
155			return append(tabShortcuts, sc...)
156		case StateDetails:
157			return shortcut.Shortcuts{
158				{Key: "esc", Description: "Go back to the checks"},
159			}
160		}
161		return tabShortcuts
162	}
