164	// GetHeaderInfo implements HeaderView.
165	//
166	// The verdict is the one line worth spending: it is the answer to the question
167	// the view exists for, and reading it off ten rows is what the header is
168	// supposed to save. It appears only once there is a run to summarise.
169	func (m *Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
170		info := []shortcut.HeaderInfo{
171			{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
172		}
173		if m.activeTab == tabInterfaces {
174			return append(info, shortcut.HeaderInfo{
175				Key:   "Interfaces",
176				Value: m.interfacesModel.summaryLine(),
177				Style: theme.HeaderValueStyle,
178			})
179		}
180		if m.activeTab == tabPorts {
181			return append(info, shortcut.HeaderInfo{
182				Key:   "Ports",
183				Value: m.portsModel.summaryLine(),
184				Style: theme.HeaderValueStyle,
185			})
186		}
187		if m.activeTab == tabForward {
188			return append(info, shortcut.HeaderInfo{
189				Key:   "Forwards",
190				Value: m.forwardModel.summaryLine(),
191				Style: theme.HeaderValueStyle,
192			})
193		}
194		if m.state == StateTrace {
195			return append(info, m.pathModel.headerInfo()...)
196		}
197		if m.activeTab != tabDiagnostics || m.state == StateInput {
198			return info
199		}
200		if len(m.results.All()) == 0 {
201			return info
202		}
203		return append(info, shortcut.HeaderInfo{
204			Key:   "Verdict",
205			Value: m.verdict.String(),
206			Style: verdictHeaderStyle(m.verdict),
207		})
208	}
