244	// RenderFooter implements FooterView
245	func (m *Model) RenderFooter(width int) string {
246		var parts []string
247	
248		// The active tab's filter bar renders above the tab bar when visible.
249		switch {
250		case m.activeTab == tabPorts && m.portsModel.table.FilterBar().IsVisible():
251			parts = append(parts, m.portsModel.table.FilterBar().View())
252		case m.activeTab == tabDiagnostics && !m.inTrace() && m.filterBar.IsVisible():
253			parts = append(parts, m.filterBar.View())
254		case m.activeTab == tabInterfaces && m.interfacesModel.table.FilterBar().IsVisible():
255			parts = append(parts, m.interfacesModel.table.FilterBar().View())
256		case m.activeTab == tabForward && m.forwardModel.table.FilterBar().IsVisible():
257			parts = append(parts, m.forwardModel.table.FilterBar().View())
258		}
259	
260		tabs := theme.RenderTabs([]theme.TabItem{
261			{Label: "Diagnostics"},
262			{Label: "Ports"},
263			{Label: "Interfaces"},
264			{Label: "Forward"},
265		}, m.activeTab)
266		tabBar := theme.PadWithBg(theme.Bg(" ")+tabs, width)
267	
268		// The message belongs to the tab that raised it: each sub-model keeps its
269		// own, so switching away does not carry one tab's notice onto another.
270		footer, status := m.activeFooter()
271		parts = append(parts, tabBar, theme.EmptyLineBg(width), footer.View(width, status))
272		return strings.Join(parts, "\n")
273	}
