275	// activeFooter resolves the message line of whichever tab is on screen, and the
276	// status that tab derives on every frame.
277	func (m *Model) activeFooter() (*components.FooterMessage, components.Status) {
278		switch m.activeTab {
279		case tabPorts:
280			return &m.portsModel.footer, m.portsModel.statusLine()
281		case tabInterfaces:
282			return &m.interfacesModel.footer, m.interfacesModel.statusLine()
283		case tabForward:
284			return &m.forwardModel.footer, m.forwardModel.status()
285		}
286		if m.state == StateTrace {
287			return &m.pathModel.footer, m.pathModel.statusLine()
288		}
289		return &m.footer, m.statusLine()
290	}
291	
292	// statusLine is what the diagnostics tab derives on every frame: a progress
293	// label while the pipeline walks, and nothing once it has an answer. It is a
294	// status rather than a footer message because it is a state, not an event —
295	// a message expires after three seconds and a run outlives that (Rule 128).
296	func (m *Model) statusLine() components.Status {
297		if m.state == StateRunning {
298			return components.Status{Text: m.progressLabel(), Activity: true}
299		}
300		if m.state == StateInput {
301			if st := m.traceValidation.Status(); st.Text != "" {
302				return st
303			}
304		}
305		if m.state == StateInput {
306			if a := m.traceable(); !a.Enabled() {
307				return components.Status{Text: a.Reason, Level: components.LevelWarning}
308			}
309		}
310		return components.Status{}
311	}
